using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends a code to the specified phone number. Aborts previous phone number verification if there was one. On success, returns information about the sent code
    /// </summary>
    public Task<TdLib.TdApi.Objects.AuthenticationCodeInfo> SendPhoneNumberCodeAsync(string phoneNumber = default, PhoneNumberAuthenticationSettings settings = default, PhoneNumberCodeType type = default)
    {

           using var activity =  StartCallActivity("SendPhoneNumberCodeAsync", typeof(SendPhoneNumberCode).FullName ?? "SendPhoneNumberCodeAsync");

           try
           {
             return client.SendPhoneNumberCodeAsync(phoneNumber, settings, type);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
